async function returnToEarth(){const button=$('returnEarth');button.disabled=true;try{if(!state.run||!state.selected)throw new Error('Select a trajectory first.');$('returnEarthStatus').textContent='Searching Earth-return dates while retaining the outbound trip…';const result=await api('/api/return-earth',{run:state.run,candidate:state.selected,minimum_days:+$('returnMinDays').value,maximum_days:+$('returnMaxDays').value,dsm:$('returnDsm').checked});$('detail').close();state.busy=true;await refreshRuns();await openRun(result.run);message('Earth-return search started. Outbound trajectory locked; all turnaround and DSM impulses count toward the saved limits.');}catch(e){$('returnEarthStatus').textContent=e.message;button.disabled=false;}}
