function appendTargetMode(){return document.querySelector('input[name=appendTargetMode]:checked').value;}
function changeAppendMode(){const custom=appendTargetMode()==='object';$('appendPlanetBox').hidden=custom;$('appendObjectBox').hidden=!custom;$('appendCountLabel').hidden=custom;if(custom&&+$('appendMaxDays').value===750){$('appendMinDays').value=180;$('appendMaxDays').value=3000;}}
function appendTargetInfo(result){const box=$('appendObjectInfo');box.replaceChildren();if(result.ambiguous){box.append(element('p','Several matches. Choose the intended target:'));for(const choice of result.choices||[]){const button=element('button',(choice.name||choice.designation)+(choice.type?' · '+choice.type:'')+' · ID '+choice.id);button.type='button';button.onclick=()=>{$('appendObjectName').value=choice.designation||('SPK='+choice.id);resolveAppendTarget();};box.append(button);}return;}state.appendTarget=result;box.append(element('strong',result.name),element('div','Horizons ID '+result.id));if(result.model_limitation){state.appendTarget=null;box.append(element('p',result.model_limitation,'error'));}else box.append(element('div','Resolved. The earlier cruise stays fixed; any minor-body retargeting burn counts toward the budget.'));}
async function resolveAppendTarget(){const button=$('resolveAppendObject');button.disabled=true;state.appendTarget=null;$('appendObjectInfo').textContent='Resolving follow-on target with JPL…';try{const epoch=state.card?.arrival_date?.slice(0,10)||$('launchStart').value;appendTargetInfo(await api('/api/resolve',{query:$('appendObjectName').value,epoch}));}catch(e){$('appendObjectInfo').textContent=e.message;}finally{button.disabled=false;}}
document.querySelectorAll('input[name=appendTargetMode]').forEach(input=>input.onchange=changeAppendMode);$('resolveAppendObject').onclick=resolveAppendTarget;$('appendObjectName').oninput=()=>{state.appendTarget=null;$('appendObjectInfo').textContent='Resolve this follow-on designation before searching.';};


function showCommunity(value){
 state.community=value;$('communityShare').checked=value.share_candidates;$('communityUse').checked=value.use_candidates;$('communityEndpoint').value=value.endpoint||'';
 $('communityStatus').textContent=value.configured?(value.share_candidates?'Sharing on. New pass/yellow solutions are uploaded during searches.':'Sharing off. No future candidate uploads.'):'Community API is not configured. Nothing is being uploaded.';
}
async function saveCommunity(){try{showCommunity(await api('/api/community-settings',{share_candidates:$('communityShare').checked,use_candidates:$('communityUse').checked,endpoint:$('communityEndpoint').value}));}catch(e){if(state.community)showCommunity(state.community);$('communityStatus').textContent=e.message;}}
$('communityShare').onchange=()=>{if(!$('communityShare').checked&&!confirm('Shared trajectories help everyone find better missions without repeating computations. Turning sharing off stops future uploads; your searches and downloads will still work. Already shared solutions remain public. Turn off sharing?')){$('communityShare').checked=true;return;}saveCommunity();};
$('communityUse').onchange=saveCommunity;$('communitySave').onclick=saveCommunity;

